  let n = nums.length;
  let max = -Infinity, min = Infinity;
  let end = -1, start = -1;
  for (let i = 0; i < n; i++) {
    max = Math.max(max, nums[i]);
    if (nums[i] < max) end = i;
    const j = n - 1 - i;
    min = Math.min(min, nums[j]);
    if (nums[j] > min) start = j;
  }
  return end === -1 ? 0 : end - start + 1;
}

